PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS snapshots(id TEXT PRIMARY KEY,schema_version INTEGER NOT NULL,parser_versions_json TEXT NOT NULL,inclusion_policy_json TEXT NOT NULL,status TEXT NOT NULL,source_complete INTEGER NOT NULL,manifest_json TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,locked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS file_blobs(sha256 TEXT PRIMARY KEY,bytes BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS files(snapshot_id TEXT REFERENCES snapshots(id),path TEXT,language TEXT,blob_hash TEXT REFERENCES file_blobs(sha256),parse_status TEXT,coverage_json TEXT,PRIMARY KEY(snapshot_id,path));
CREATE TABLE IF NOT EXISTS functions(id TEXT PRIMARY KEY,snapshot_id TEXT,path TEXT,parent_id TEXT REFERENCES functions(id) DEFERRABLE INITIALLY DEFERRED,kind TEXT,name TEXT,qualified_name TEXT,start_byte INTEGER,end_byte INTEGER,body_start_byte INTEGER,body_end_byte INTEGER,source_hash TEXT,flags_json TEXT,node_kind TEXT,record_json TEXT,FOREIGN KEY(snapshot_id,path) REFERENCES files(snapshot_id,path),UNIQUE(snapshot_id,path,start_byte,end_byte,node_kind));
CREATE INDEX IF NOT EXISTS canonical_functions ON functions(snapshot_id,path COLLATE BINARY,start_byte,end_byte,node_kind COLLATE BINARY,id COLLATE BINARY);
CREATE TABLE IF NOT EXISTS gaps(snapshot_id TEXT,path TEXT,kind TEXT,start_byte INTEGER,end_byte INTEGER,details_json TEXT,FOREIGN KEY(snapshot_id,path) REFERENCES files(snapshot_id,path));
CREATE TABLE IF NOT EXISTS dispatch_runs(id TEXT PRIMARY KEY,snapshot_id TEXT REFERENCES snapshots(id),analyzer_config_hash TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dispatch_items(run_id TEXT REFERENCES dispatch_runs(id),function_id TEXT REFERENCES functions(id),status TEXT NOT NULL CHECK(status IN ('pending','claimed','completed','failed_retryable','failed_final')),attempt INTEGER NOT NULL DEFAULT 0,result_json TEXT,error_json TEXT,PRIMARY KEY(run_id,function_id));
CREATE TABLE IF NOT EXISTS dispatch_events(sequence INTEGER PRIMARY KEY,run_id TEXT,function_id TEXT,event TEXT,attempt INTEGER,details_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(run_id,function_id) REFERENCES dispatch_items(run_id,function_id));
CREATE TRIGGER IF NOT EXISTS snapshot_update BEFORE UPDATE ON snapshots WHEN OLD.locked=1 BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS snapshot_delete BEFORE DELETE ON snapshots BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS blob_update BEFORE UPDATE ON file_blobs BEGIN SELECT RAISE(ABORT,'immutable blob'); END;
CREATE TRIGGER IF NOT EXISTS blob_delete BEFORE DELETE ON file_blobs BEGIN SELECT RAISE(ABORT,'immutable blob'); END;
CREATE TRIGGER IF NOT EXISTS files_insert BEFORE INSERT ON files WHEN (SELECT locked FROM snapshots WHERE id=NEW.snapshot_id)=1 BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS files_update BEFORE UPDATE ON files BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS files_delete BEFORE DELETE ON files BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS functions_insert BEFORE INSERT ON functions WHEN (SELECT locked FROM snapshots WHERE id=NEW.snapshot_id)=1 BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS functions_update BEFORE UPDATE ON functions BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS functions_delete BEFORE DELETE ON functions BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS gaps_insert BEFORE INSERT ON gaps WHEN (SELECT locked FROM snapshots WHERE id=NEW.snapshot_id)=1 BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS gaps_update BEFORE UPDATE ON gaps BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TRIGGER IF NOT EXISTS gaps_delete BEFORE DELETE ON gaps BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TABLE IF NOT EXISTS analysis_runs(run_id TEXT PRIMARY KEY REFERENCES dispatch_runs(id),config_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS weakness_plan(run_id TEXT REFERENCES analysis_runs(run_id),language TEXT NOT NULL,weakness_id TEXT NOT NULL,disposition TEXT NOT NULL CHECK(disposition IN ('finding','gate','skipped')),reason TEXT,PRIMARY KEY(run_id,language,weakness_id));
CREATE TABLE IF NOT EXISTS weakness_decisions(run_id TEXT NOT NULL,function_id TEXT NOT NULL,weakness_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('finding','gate')),round INTEGER NOT NULL,origin TEXT NOT NULL CHECK(origin IN ('provider','cache','refused','gated','trait')),probability REAL,question_hash TEXT,reason TEXT,PRIMARY KEY(run_id,function_id,weakness_id),FOREIGN KEY(run_id,function_id) REFERENCES dispatch_items(run_id,function_id));
CREATE INDEX IF NOT EXISTS weakness_findings ON weakness_decisions(run_id,role,probability);
CREATE TABLE IF NOT EXISTS decision_cache(provider_key TEXT NOT NULL,language TEXT NOT NULL,source_hash TEXT NOT NULL,question_hash TEXT NOT NULL,probability REAL NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(provider_key,language,source_hash,question_hash));
PRAGMA user_version=3;
